import java.io.*;
import java.security.MessageDigest;
import java.util.*;

/** Teaching envelope; only synthetic payloads belong in this lab. */
public record EventEnvelope(String eventId, String payload, int attempt, long deadlineMillis) {
    public static final int MAX_WIRE = 32768;
    public static final int MAX_PAYLOAD_UTF8 = 16000;
    public EventEnvelope {
        if (eventId == null || !eventId.matches("[A-Za-z0-9_.:-]{1,80}")
                || payload == null || payload.length() > MAX_PAYLOAD_UTF8
                || attempt < 0 || attempt > 2 || deadlineMillis <= 0)
            throw new IllegalArgumentException("invalid envelope");
        wireSize(eventId, payload); // validate before allocating encoded byte arrays
    }
    private static int wireSize(String id, String text) {
        int utf8 = 0, modifiedUtf8 = 0;
        for (int i = 0; i < text.length(); i++) {
            char c = text.charAt(i);
            if (Character.isHighSurrogate(c)) {
                if (i + 1 >= text.length() || !Character.isLowSurrogate(text.charAt(i + 1)))
                    throw new IllegalArgumentException("ill-formed UTF-16");
                i++; utf8 += 4; modifiedUtf8 += 6;
            } else if (Character.isLowSurrogate(c)) {
                throw new IllegalArgumentException("ill-formed UTF-16");
            } else {
                utf8 += c <= 0x7f ? 1 : c <= 0x7ff ? 2 : 3;
                modifiedUtf8 += c == 0 ? 2 : c <= 0x7f ? 1 : c <= 0x7ff ? 2 : 3;
            }
            if (utf8 > MAX_PAYLOAD_UTF8) throw new IllegalArgumentException("payload too large");
        }
        // Version, two UTF length prefixes, attempt and deadline take 20 bytes.
        int size = 20 + id.length() + modifiedUtf8; // eventId is bounded ASCII
        if (size > MAX_WIRE) throw new IllegalArgumentException("envelope too large");
        return size;
    }
    public EventEnvelope retry() { return new EventEnvelope(eventId, payload, attempt + 1, deadlineMillis); }
    public byte[] encode() throws IOException {
        var bytes = new ByteArrayOutputStream(wireSize(eventId, payload));
        try (var out = new DataOutputStream(bytes)) {
            out.writeInt(1); out.writeUTF(eventId); out.writeUTF(payload);
            out.writeInt(attempt); out.writeLong(deadlineMillis);
        }
        return bytes.toByteArray();
    }
    public static EventEnvelope decode(byte[] bytes) throws IOException {
        if (bytes.length > MAX_WIRE) throw new IOException("oversized");
        try (var in = new DataInputStream(new ByteArrayInputStream(bytes))) {
            if (in.readInt() != 1) throw new IOException("unknown schema");
            var e = new EventEnvelope(in.readUTF(), in.readUTF(), in.readInt(), in.readLong());
            if (in.available() != 0) throw new IOException("trailing bytes");
            return e;
        } catch (IllegalArgumentException e) { throw new IOException("invalid envelope", e); }
    }
    public static String hash(byte[] bytes) {
        try { return HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(bytes)); }
        catch (Exception impossible) { throw new AssertionError(impossible); }
    }
}

import com.rabbitmq.client.*;
import java.util.*;
import java.util.concurrent.*;

/** Local-only, fixed-deadline connection owner. Never use production credentials. */
public final class LabRuntime implements AutoCloseable {
    private final List<Connection> connections = new CopyOnWriteArrayList<>();
    private final ScheduledExecutorService deadline = Executors.newSingleThreadScheduledExecutor(r -> {
        Thread t = new Thread(r, "rabbit-lab-wall-deadline"); t.setDaemon(true); return t;
    });
    private volatile boolean closed;
    public LabRuntime() { deadline.schedule(this::abortAll, 20, TimeUnit.SECONDS); }
    public static void requireLocalOptIn(String[] args) {
        if (args.length != 1 || !"--local-lab".equals(args[0]))
            throw new IllegalArgumentException("explicit --local-lab required; local disposable broker only");
    }
    public Connection connect() throws Exception {
        if (closed) throw new IllegalStateException("deadline/closed");
        var f = new ConnectionFactory();
        f.setHost("127.0.0.1"); f.setPort(5672);
        // Client defaults are usable only for a local disposable installation.
        // No credential is printed or persisted by this program.
        f.setAutomaticRecoveryEnabled(false); f.setTopologyRecoveryEnabled(false);
        f.setConnectionTimeout(2000); f.setHandshakeTimeout(2000);
        f.setChannelRpcTimeout(2000); f.setShutdownTimeout(1000);
        f.setRequestedHeartbeat(5); f.setMaxInboundMessageBodySize(EventEnvelope.MAX_WIRE);
        f.setThreadFactory(r -> { Thread t = new Thread(r, "rabbit-lab-client"); t.setDaemon(true); return t; });
        Connection c = f.newConnection("bounded-interview-lab");
        connections.add(c);
        if (closed) {
            var failure = new IllegalStateException("deadline during connection");
            RabbitCleanup.after(failure, () -> c.abort(500));
            throw failure;
        }
        return c;
    }
    private void abortAll() {
        closed = true;
        RuntimeException failure = null;
        for (Connection c : connections) {
            try { c.abort(500); }
            catch (RuntimeException next) {
                if (failure == null) failure = next; else RabbitCleanup.attach(failure, next);
            }
        }
        connections.clear();
        if (failure != null) throw failure;
    }
    @Override public void close() {
        Throwable primary = null;
        try { abortAll(); }
        catch (RuntimeException | Error failure) { primary = failure; throw failure; }
        finally {
            Throwable original = primary;
            RabbitCleanup.after(original, () -> {
                deadline.shutdownNow();
                try { if (!deadline.awaitTermination(2, TimeUnit.SECONDS)) throw new IllegalStateException("timer remains"); }
                catch (InterruptedException e) { Thread.currentThread().interrupt(); throw new IllegalStateException(e); }
            });
        }
    }
}

/** Narrow synchronous cleanup helper; actions must provide their own time bounds. */
public final class RabbitCleanup {
    private RabbitCleanup() { }
    public static void preserveInterrupt(Throwable failure) {
        if (failure instanceof InterruptedException) Thread.currentThread().interrupt();
    }
    public static void attach(Throwable primary, Throwable secondary) {
        preserveInterrupt(secondary);
        if (primary != secondary) primary.addSuppressed(secondary);
    }
    public static void after(Throwable primary, Runnable cleanup) {
        try { cleanup.run(); }
        catch (RuntimeException | Error secondary) {
            if (primary == null) throw secondary;
            attach(primary, secondary);
        }
    }
}

import com.rabbitmq.client.*;
import java.io.*;
import java.util.*;
import java.util.concurrent.*;
import java.util.concurrent.atomic.AtomicBoolean;

public final class RabbitConsumerLab {
    public enum Effect { COMMITTED, RETRYABLE, PERMANENT, UNKNOWN }
    /** COMMITTED means durable effect/receipt, or durable responsibility transfer in a real adapter.
     * A production adapter must enforce its own I/O deadline and authoritative identity checks. */
    public interface EffectPort { Effect apply(EventEnvelope e) throws Exception; }
    public interface Handoff { RabbitPublisherLab.Outcome send(String route, String eventId, byte[] body) throws Exception; }
    public interface AckPort { void ack(long tag) throws Exception; }
    public record Delivery(UUID generation, long tag, String exchange, String route,
                           String messageId, String publishAttempt, boolean redelivered, long redeliveryCount, byte[] body) {
        public Delivery {
            Objects.requireNonNull(generation); Objects.requireNonNull(body);
            exchange = Objects.toString(exchange, ""); route = Objects.toString(route, "");
            messageId = Objects.toString(messageId, ""); publishAttempt = Objects.toString(publishAttempt, "");
            body = body.clone();
        }
        public Delivery(UUID g, long tag, String exchange, String route, byte[] body) {
            this(g, tag, exchange, route, "", "", false, 0, body);
        }
        @Override public byte[] body() { return body.clone(); }
    }
    public enum Result { ACKED, STOP_UNACKED, STALE }
    public static Result handle(UUID current, Delivery d, EffectPort service, Handoff handoff,
                                AckPort acknowledger, long nowMillis) throws Exception {
        if (!current.equals(d.generation())) return Result.STALE;
        if (d.tag() <= 0) throw new IllegalArgumentException("positive channel delivery tag required");
        EventEnvelope e;
        try { e = EventEnvelope.decode(d.body()); }
        catch (IOException malformed) { return quarantine(d, "malformed-schema", handoff, acknowledger); }
        Effect effect;
        try { effect = service.apply(e); }
        catch (InterruptedException interrupted) {
            Thread.currentThread().interrupt();
            return Result.STOP_UNACKED;
        }
        catch (Exception unknown) { return Result.STOP_UNACKED; } // DB unavailable / COMMIT ambiguous
        if (effect == null || effect == Effect.UNKNOWN) return Result.STOP_UNACKED; // query same identity; no blind retry
        if (effect == Effect.COMMITTED) {
            acknowledger.ack(d.tag()); // kept outside business catch: ACK failure never rewinds effect
            return Result.ACKED;
        }
        if (effect == Effect.PERMANENT || e.attempt() == 2 || nowMillis >= e.deadlineMillis())
            return quarantine(d, effect == Effect.PERMANENT ? "permanent" : "retry-budget-exhausted", handoff, acknowledger);
        long delay = (20L << e.attempt()) + Math.floorMod(e.eventId().hashCode(), 11);
        if (e.deadlineMillis() - nowMillis <= delay + 1600)
            return quarantine(d, "deadline-insufficient", handoff, acknowledger);
        // Small bounded lab backoff while original stays unacked. A crash leaves broker responsibility.
        // For long delays use durable dueAt/Outbox, not a sleeping worker.
        Thread.sleep(delay);
        RabbitPublisherLab.Outcome o = handoff.send("work", e.eventId(), e.retry().encode());
        if (o != RabbitPublisherLab.Outcome.ACK_ROUTED) return Result.STOP_UNACKED;
        acknowledger.ack(d.tag()); // confirm-before-ACK: a crash here can duplicate, cannot erase both copies
        return Result.ACKED;
    }
    private static Result quarantine(Delivery d, String reason, Handoff h, AckPort ack) throws Exception {
        byte[] raw = d.body();
        if (raw.length > EventEnvelope.MAX_WIRE - 1024) return Result.STOP_UNACKED;
        String hash = EventEnvelope.hash(raw);
        String id;
        try { id = EventEnvelope.decode(raw).eventId(); } catch (IOException invalid) { id = "raw-" + hash; }
        var bytes = new ByteArrayOutputStream();
        try (var out = new DataOutputStream(bytes)) {
            out.writeInt(2); out.writeUTF(id); out.writeUTF(reason);
            out.writeUTF(d.exchange()); out.writeUTF(d.route());
            out.writeUTF(d.generation().toString()); out.writeLong(d.tag());
            out.writeLong(System.currentTimeMillis()); out.writeUTF(hash);
            out.writeUTF(d.messageId()); out.writeUTF(d.publishAttempt());
            out.writeBoolean(d.redelivered()); out.writeLong(d.redeliveryCount());
            out.writeInt(raw.length); out.write(raw); // complete bytes; do not log private payloads
        }
        if (bytes.size() > EventEnvelope.MAX_WIRE) return Result.STOP_UNACKED;
        if (h.send("dead", id, bytes.toByteArray()) != RabbitPublisherLab.Outcome.ACK_ROUTED)
            return Result.STOP_UNACKED;
        ack.ack(d.tag());
        return Result.ACKED;
    }
    /** Process-local mock ONLY: loss on restart is deliberate, not a durable inbox implementation. */
    public static final class MockEffects implements EffectPort {
        private final Map<String, String> completed = new HashMap<>();
        private int count;
        @Override public Effect apply(EventEnvelope e) {
            String identityPayload = e.payload() + "\n" + e.deadlineMillis();
            String prior = completed.get(e.eventId());
            if (prior != null) return prior.equals(identityPayload) ? Effect.COMMITTED : Effect.PERMANENT;
            if (System.currentTimeMillis() >= e.deadlineMillis()) return Effect.PERMANENT;
            if (e.payload().equals("unknown")) return Effect.UNKNOWN;
            if (e.payload().equals("permanent")) return Effect.PERMANENT;
            if (e.payload().equals("transient") && e.attempt() < 2) return Effect.RETRYABLE;
            if (completed.size() == 32) return Effect.UNKNOWN;
            completed.put(e.eventId(), identityPayload); count++;
            return Effect.COMMITTED;
        }
        public int count() { return count; }
    }
    public static void main(String[] args) throws Exception {
        LabRuntime.requireLocalOptIn(args);
        UUID generation = UUID.randomUUID();
        var inbox = new ArrayBlockingQueue<Delivery>(RabbitTopology.PREFETCH);
        var stopped = new AtomicBoolean();
        var mock = new MockEffects();
        try (var runtime = new LabRuntime();
             var publisher = new RabbitPublisherLab(new RealRabbitWire(runtime), 4)) {
            Connection connection = runtime.connect();
            Channel ch = connection.createChannel();
            RabbitTopology.declare(ch); ch.basicQos(RabbitTopology.PREFETCH, false);
            ch.addShutdownListener(s -> stopped.set(true));
            String consumer = ch.basicConsume(RabbitTopology.WORK, false,
                    (tag, message) -> {
                        var env = message.getEnvelope();
                        var props = message.getProperties();
                        Object count = props.getHeaders() == null ? null : props.getHeaders().get("x-delivery-count");
                        var d = new Delivery(generation, env.getDeliveryTag(), env.getExchange(), env.getRoutingKey(),
                                props.getMessageId(), props.getCorrelationId(), env.isRedeliver(),
                                count instanceof Number n ? n.longValue() : 0, message.getBody());
                        if (!inbox.offer(d)) { stopped.set(true); connection.abort(500); }
                    }, tag -> stopped.set(true));
            long until = System.nanoTime() + TimeUnit.SECONDS.toNanos(12);
            int deliveries = 0;
            Throwable processingFailure = null;
            try {
                while (!stopped.get() && System.nanoTime() < until && deliveries < 12) {
                    Delivery d = inbox.poll(100, TimeUnit.MILLISECONDS);
                    if (d == null) continue;
                    deliveries++;
                    Result result = handle(generation, d, mock,
                            (route, event, body) -> publisher.publish(route, event, body, 1500).await(1800),
                            tag -> ch.basicAck(tag, false), System.currentTimeMillis());
                    if (result != Result.ACKED) { stopped.set(true); break; }
                }
            } catch (Exception | Error failure) {
                processingFailure = failure;
                RabbitCleanup.preserveInterrupt(failure);
                throw failure;
            } finally {
                // No ACK for unprocessed queued work. Cleanup cannot replace processing failure.
                try { RabbitCleanup.after(processingFailure, () -> connection.abort(500)); }
                finally { inbox.clear(); }
            }
            System.out.println("Mock effects=" + mock.count() + ", deliveries=" + deliveries
                    + "; no database, no provider, no restart-persistent effects");
        }
    }
}

import com.rabbitmq.client.Connection;
import java.lang.reflect.Proxy;
import java.util.UUID;

/** Bounded fault doubles: no sockets, credentials, broker or database. */
public final class RabbitFailureTests {
    static int checks;
    static void check(boolean ok) { checks++; if (!ok) throw new AssertionError("check " + checks); }
    static final class NoSuppression extends RuntimeException {
        private static final long serialVersionUID = 1L;
        NoSuppression() { super("primary", null, false, true); }
    }
    static final class Wire implements RabbitPublisherLab.Wire {
        Exception sendFailure; RuntimeException abortFailure; boolean aborted;
        public void listen(UUID generation, RabbitPublisherLab.Listener listener) { }
        public long nextSequence() { return 1; }
        public void send(String route, String id, String attempt, byte[] body) throws Exception { throw sendFailure; }
        public void abort() { aborted = true; if (abortFailure != null) throw abortFailure; }
    }
    static Connection connection(RuntimeException primary, RuntimeException cleanup) {
        return (Connection) Proxy.newProxyInstance(RabbitFailureTests.class.getClassLoader(),
                new Class<?>[]{Connection.class}, (proxy, method, args) -> {
                    if (method.getName().equals("createChannel")) throw primary;
                    if (method.getName().equals("abort")) throw cleanup;
                    throw new UnsupportedOperationException(method.getName());
                });
    }
    static java.util.concurrent.ScheduledThreadPoolExecutor timer(RabbitPublisherLab publisher)
            throws ReflectiveOperationException {
        java.lang.reflect.Field field = RabbitPublisherLab.class.getDeclaredField("watchdog");
        field.setAccessible(true);
        return (java.util.concurrent.ScheduledThreadPoolExecutor) field.get(publisher);
    }

    static void alreadyTerminated() throws Exception {
        Wire wire = new Wire();
        wire.abortFailure = new IllegalStateException("abort failed");
        RabbitPublisherLab publisher = new RabbitPublisherLab(wire, 1);
        try {
            var timer = timer(publisher);
            timer.shutdownNow();
            check(timer.awaitTermination(2, java.util.concurrent.TimeUnit.SECONDS));
            Thread.currentThread().interrupt();
            try {
                publisher.close();
                throw new AssertionError("close should preserve abort failure");
            } catch (RuntimeException actual) {
                check(actual == wire.abortFailure);
                check(actual.getSuppressed().length == 0);
                check(Thread.currentThread().isInterrupted());
            }
        } finally {
            Thread.interrupted();
            publisher.close();
        }
    }

    static void stillRunning() throws Exception {
        Wire wire = new Wire();
        wire.abortFailure = new IllegalStateException("abort failed");
        RabbitPublisherLab publisher = new RabbitPublisherLab(wire, 1);
        var started = new java.util.concurrent.CountDownLatch(1);
        var release = new java.util.concurrent.CountDownLatch(1);
        try {
            var timer = timer(publisher);
            timer.execute(() -> {
                started.countDown();
                while (release.getCount() > 0) {
                    try {
                        release.await();
                    } catch (InterruptedException ignored) {
                        // Keep the test worker alive until the outer cleanup releases it.
                    }
                }
            });
            check(started.await(2, java.util.concurrent.TimeUnit.SECONDS));
            Thread.currentThread().interrupt();
            try {
                publisher.close();
                throw new AssertionError("close should preserve abort failure");
            } catch (RuntimeException actual) {
                check(actual == wire.abortFailure);
                check(actual.getSuppressed().length == 1);
                check(actual.getSuppressed()[0].getCause() instanceof InterruptedException);
                check(Thread.currentThread().isInterrupted());
            }
        } finally {
            Thread.interrupted();
            release.countDown();
            publisher.close();
        }
    }

    public static void main(String[] args) throws Exception {
        alreadyTerminated();
        stillRunning();
        RuntimeException same = new IllegalStateException("same");
        try { new RealRabbitWire(connection(same, same)); throw new AssertionError(); }
        catch (RuntimeException actual) { check(actual == same && actual.getSuppressed().length == 0); }
        RuntimeException first = new IllegalStateException("first"), second = new IllegalStateException("second");
        try { new RealRabbitWire(connection(first, second)); throw new AssertionError(); }
        catch (RuntimeException actual) { check(actual == first && actual.getSuppressed()[0] == second); }
        NoSuppression disabled = new NoSuppression();
        try { new RealRabbitWire(connection(disabled, second)); throw new AssertionError(); }
        catch (RuntimeException actual) { check(actual == disabled && actual.getSuppressed().length == 0); }
        Wire invalid = new Wire(); invalid.abortFailure = second;
        try { new RabbitPublisherLab(invalid, 0); throw new AssertionError(); }
        catch (IllegalArgumentException actual) { check(invalid.aborted && actual.getSuppressed()[0] == second); }
        Wire interrupted = new Wire(); interrupted.sendFailure = new InterruptedException("send interrupted"); interrupted.abortFailure = second;
        RabbitPublisherLab publisher = new RabbitPublisherLab(interrupted, 1);
        try {
            var ticket = publisher.publish("work", "e", new byte[]{1}, 1000);
            check(ticket.outcome() == RabbitPublisherLab.Outcome.UNKNOWN);
            check(ticket.failure() == interrupted.sendFailure && ticket.failure().getSuppressed()[0] == second);
            check(Thread.interrupted());
        } finally { publisher.close(); }
        Wire aliased = new Wire(); aliased.sendFailure = same; aliased.abortFailure = same;
        try (var p = new RabbitPublisherLab(aliased, 1)) {
            var ticket = p.publish("work", "e", new byte[]{1}, 1000);
            check(ticket.failure() == same && same.getSuppressed().length == 0);
        }
        UUID generation = UUID.randomUUID();
        var delivery = new RabbitConsumerLab.Delivery(generation, 1, "x", "work",
                new EventEnvelope("e", "x", 0, 10).encode());
        boolean[] acked = {false};
        var result = RabbitConsumerLab.handle(generation, delivery,
                event -> { throw new InterruptedException("adapter interrupted"); },
                (route, id, body) -> { throw new AssertionError("must not hand off"); },
                tag -> acked[0] = true, 1);
        check(result == RabbitConsumerLab.Result.STOP_UNACKED && !acked[0] && Thread.interrupted());
        RabbitCleanup.after(same, () -> { throw same; }); check(same.getSuppressed().length == 0);
        RabbitCleanup.after(disabled, () -> { throw second; }); check(disabled.getSuppressed().length == 0);
        System.out.println("RabbitFailureTests OK: " + checks + "; fault doubles only");
    }
}

import java.io.*;
import java.util.*;
import java.util.concurrent.*;

/** Deterministic callback/fault tests: no socket, broker, SQL or real external action. */
public final class RabbitLabTest {
    static int checks;
    static void check(boolean b) { checks++; if (!b) throw new AssertionError("check " + checks); }
    static final class FakeWire implements RabbitPublisherLab.Wire {
        UUID generation; RabbitPublisherLab.Listener listener;
        long seq = 1; String lastAttempt; boolean aborted, failListen, failAbort;
        String behavior = "silent";
        public void listen(UUID g, RabbitPublisherLab.Listener l) throws IOException {
            generation = g; listener = l; if (failListen) throw new IOException("listen setup failed");
        }
        public long nextSequence() { return seq; }
        public void send(String route, String event, String attempt, byte[] bytes) throws Exception {
            lastAttempt = attempt; long sent = seq++;
            if (behavior.equals("throw")) throw new IOException("partial socket write");
            if (behavior.equals("return")) listener.returned(generation, attempt);
            if (!behavior.equals("silent")) listener.confirm(generation, sent, false, !behavior.equals("nack"));
        }
        public void abort() { aborted = true; if (failAbort) throw new IllegalStateException("abort failed"); }
    }
    static RabbitConsumerLab.Delivery delivery(UUID g, long tag, EventEnvelope e) throws IOException {
        return new RabbitConsumerLab.Delivery(g, tag, RabbitTopology.EXCHANGE, "work", e.encode());
    }
    public static void main(String[] args) throws Exception {
        long threadsBefore = Thread.getAllStackTraces().keySet().stream()
                .filter(t -> t.isAlive() && t.getName().startsWith("rabbit-")).count();
        // Standard UTF-8 payload budget and modified UTF-8 wire budget are distinct.
        for (String payload : List.of("", "a".repeat(16000), "\0".repeat(16000),
                "\uD83D\uDE00".repeat(4000), "界".repeat(5333))) {
            var valid = new EventEnvelope("e".repeat(80), payload, 0, 1);
            byte[] encoded = valid.encode();
            check(encoded.length <= EventEnvelope.MAX_WIRE);
            check(EventEnvelope.decode(encoded).equals(valid));
        }
        for (String payload : List.of("\uD800".repeat(16000), "\uDC00".repeat(16000),
                "\uD800", "\uDC00", "\uD800a", "a\uDC00", "a".repeat(16001),
                "\uD83D\uDE00".repeat(4001), "界".repeat(5334))) {
            try { new EventEnvelope("bad", payload, 0, 1); throw new AssertionError("accepted invalid payload"); }
            catch (IllegalArgumentException expected) { check(true); }
        }
        var malformedText = new ByteArrayOutputStream();
        try (var out = new DataOutputStream(malformedText)) {
            out.writeInt(1); out.writeUTF("bad"); out.writeUTF("\uD800"); out.writeInt(0); out.writeLong(1);
        }
        try { EventEnvelope.decode(malformedText.toByteArray()); throw new AssertionError("decoded ill-formed text"); }
        catch (IOException expected) { check(expected.getCause() instanceof IllegalArgumentException); }
        var sameFailure = new IllegalStateException("listen and abort share one failure");
        var aliasAborted = new java.util.concurrent.atomic.AtomicBoolean();
        var aliasWire = new RabbitPublisherLab.Wire() {
            public void listen(UUID id, RabbitPublisherLab.Listener listener) { throw sameFailure; }
            public long nextSequence() { return 1; }
            public void send(String route, String event, String attempt, byte[] body) { }
            public void abort() { aliasAborted.set(true); throw sameFailure; }
        };
        try { new RabbitPublisherLab(aliasWire, 1); throw new AssertionError("expected setup failure"); }
        catch (IllegalStateException expected) { check(expected == sameFailure && aliasAborted.get()); }
        var distinctFailure = new FakeWire(); distinctFailure.failListen = true; distinctFailure.failAbort = true;
        try { new RabbitPublisherLab(distinctFailure, 1); throw new AssertionError("expected setup failure"); }
        catch (IOException expected) {
            check(distinctFailure.aborted && expected.getSuppressed().length == 1
                    && expected.getSuppressed()[0] instanceof IllegalStateException);
        }
        var wire = new FakeWire();
        try (var p = new RabbitPublisherLab(wire, 2)) {
            var a = p.publish("work", "same", new byte[]{1}, 1000);
            var b = p.publish("work", "same", new byte[]{1}, 1000);
            check(!a.attemptId.equals(b.attemptId)); check(a.key.sequence() == 1 && b.key.sequence() == 2);
            check(p.publish("work", "full", new byte[]{1}, 1000).outcome() == RabbitPublisherLab.Outcome.REJECTED);
            wire.listener.returned(wire.generation, a.attemptId);
            wire.listener.confirm(UUID.randomUUID(), 2, true, true); check(p.inflight() == 2);
            wire.listener.confirm(wire.generation, 2, true, true);
            check(a.outcome() == RabbitPublisherLab.Outcome.RETURNED);
            check(b.outcome() == RabbitPublisherLab.Outcome.ACK_ROUTED); check(p.inflight() == 0);
            wire.behavior = "nack";
            check(p.publish("work", "nacked", new byte[]{2}, 1000).outcome() == RabbitPublisherLab.Outcome.NACK);
            wire.behavior = "throw";
            var unknown = p.publish("work", "part-written", new byte[]{3}, 1000);
            check(unknown.outcome() == RabbitPublisherLab.Outcome.UNKNOWN); check(p.inflight() == 0 && wire.aborted);
            wire.listener.confirm(wire.generation, unknown.key.sequence(), false, true);
            check(unknown.outcome() == RabbitPublisherLab.Outcome.UNKNOWN);
        }
        wire = new FakeWire();
        try (var p = new RabbitPublisherLab(wire, 2)) {
            var t = p.publish("work", "timeout", new byte[]{1}, 25);
            check(t.await(1000) == RabbitPublisherLab.Outcome.UNKNOWN);
            check(p.inflight() == 0);
        }
        check(wire.aborted);
        wire = new FakeWire();
